    47	    onPress,
    48	    pressOnEnter = false,
    49	    policyID = '-1',
    50	    shouldHidePaymentOptions = false,
    51	    shouldShowApproveButton = false,
    52	    shouldDisableApproveButton = false,
    53	    style,
    54	    disabledStyle,
    55	    shouldShowPersonalBankAccountOption = false,
    56	    enterKeyEventListenerPriority = 0,
    57	    confirmApproval,
    58	    useKeyboardShortcuts = false,
    59	    onPaymentOptionsShow,
    60	    onPaymentOptionsHide,
    61	    onlyShowPayElsewhere,
    62	    wrapperStyle,
    63	}: SettlementButtonProps) {
    64	    const {translate} = useLocalize();
    65	    const {isOffline} = useNetwork();
    66	    // The app would crash due to subscribing to the entire report collection if chatReportID is an empty string. So we should have a fallback ID here.
    67	    const [chatReport] = useOnyx(`${ONYXKEYS.COLLECTION.REPORT}${chatReportID || -1}`);
    68	    const [isUserValidated] = useOnyx(ONYXKEYS.USER, {selector: (user) => !!user?.validated});
    69	    const [lastPaymentMethod = '-1', lastPaymentMethodResult] = useOnyx(ONYXKEYS.NVP_LAST_PAYMENT_METHOD, {selector: (paymentMethod) => paymentMethod?.[policyID]});
    70	    const isLoadingLastPaymentMethod = isLoadingOnyxValue(lastPaymentMethodResult);
    71	    const [policy] = useOnyx(`${ONYXKEYS.COLLECTION.POLICY}${policyID}`);
    72	    const isInvoiceReport = (!isEmptyObject(iouReport) && ReportUtils.isInvoiceReport(iouReport)) || false;
    73	    const shouldShowPaywithExpensifyOption = !shouldHidePaymentOptions;
    74	    const shouldShowPayElsewhereOption = !shouldHidePaymentOptions && !isInvoiceReport;
    75	    const paymentButtonOptions = useMemo(() => {
    76	        const buttonOptions = [];
    77	        const isExpenseReport = ReportUtils.isExpenseReport(iouReport);
    78	        const paymentMethods = {
