    92	                value: CONST.IOU.PAYMENT_TYPE.ELSEWHERE,
    93	            },
    94	        };
    95	        const approveButtonOption = {
    96	            text: translate('iou.approve'),
    97	            icon: Expensicons.ThumbsUp,
    98	            value: CONST.IOU.REPORT_ACTION_TYPE.APPROVE,
    99	            disabled: !!shouldDisableApproveButton,
   100	        };
   101	        const canUseWallet = !isExpenseReport && !isInvoiceReport && currency === CONST.CURRENCY.USD;
   102	
   103	        // Only show the Approve button if the user cannot pay the expense
   104	        if (shouldHidePaymentOptions && shouldShowApproveButton) {
   105	            return [approveButtonOption];
   106	        }
   107	
   108	        if (onlyShowPayElsewhere) {
   109	            return [paymentMethods[CONST.IOU.PAYMENT_TYPE.ELSEWHERE]];
   110	        }
   111	
   112	        // To achieve the one tap pay experience we need to choose the correct payment type as default.
   113	        if (canUseWallet) {
   114	            buttonOptions.push(paymentMethods[CONST.IOU.PAYMENT_TYPE.EXPENSIFY]);
   115	        }
   116	        if (isExpenseReport && shouldShowPaywithExpensifyOption) {
   117	            buttonOptions.push(paymentMethods[CONST.IOU.PAYMENT_TYPE.VBBA]);
   118	        }
   119	        if (shouldShowPayElsewhereOption) {
   120	            buttonOptions.push(paymentMethods[CONST.IOU.PAYMENT_TYPE.ELSEWHERE]);
   121	        }
   122	
   123	        if (isInvoiceReport) {
   124	            if (ReportUtils.isIndividualInvoiceRoom(chatReport)) {
   125	                buttonOptions.push({
   126	                    text: translate('iou.settlePersonal', {formattedAmount}),
