   168	        // eslint-disable-next-line react-compiler/react-compiler, react-hooks/exhaustive-deps
   169	    }, [
   170	        isLoadingLastPaymentMethod,
   171	        iouReport,
   172	        translate,
   173	        formattedAmount,
   174	        shouldDisableApproveButton,
   175	        isInvoiceReport,
   176	        currency,
   177	        shouldHidePaymentOptions,
   178	        shouldShowApproveButton,
   179	        shouldShowPaywithExpensifyOption,
   180	        shouldShowPayElsewhereOption,
   181	        chatReport,
   182	        onPress,
   183	        onlyShowPayElsewhere,
   184	    ]);
   185	
   186	    const selectPaymentType = (event: KYCFlowEvent, iouPaymentType: PaymentMethodType, triggerKYCFlow: TriggerKYCFlow) => {
   187	        if (policy && SubscriptionUtils.shouldRestrictUserBillableActions(policy.id)) {
   188	            Navigation.navigate(ROUTES.RESTRICTED_ACTION.getRoute(policy.id));
   189	            return;
   190	        }
   191	
   192	        if (iouPaymentType === CONST.IOU.PAYMENT_TYPE.EXPENSIFY || iouPaymentType === CONST.IOU.PAYMENT_TYPE.VBBA) {
   193	            if (!isUserValidated) {
   194	                Navigation.navigate(ROUTES.SETTINGS_WALLET_VERIFY_ACCOUNT.route);
   195	                return;
   196	            }
   197	            triggerKYCFlow(event, iouPaymentType);
   198	            BankAccounts.setPersonalBankAccountContinueKYCOnSuccess(ROUTES.ENABLE_PAYMENTS);
   199	            return;
   200	        }
   201	
   202	        if (iouPaymentType === CONST.IOU.REPORT_ACTION_TYPE.APPROVE) {
   203	            if (confirmApproval) {
   204	                confirmApproval();
   205	            } else {
   206	                IOU.approveMoneyRequest(iouReport);
   207	            }
   208	            return;
   209	        }
   210	
   211	        playSound(SOUNDS.SUCCESS);
   212	        onPress(iouPaymentType);
   213	    };
   214	
   215	    const savePreferredPaymentMethod = (id: string, value: PaymentMethodType) => {
   216	        IOU.savePreferredPaymentMethod(id, value);
   217	    };
   218	
   219	    return (
   220	        <KYCWall
   221	            onSuccessfulKYC={(paymentType) => onPress(paymentType)}
   222	            enablePaymentsRoute={enablePaymentsRoute}
   223	            addBankAccountRoute={addBankAccountRoute}
   224	            addDebitCardRoute={addDebitCardRoute}
   225	            isDisabled={isOffline}
   226	            source={CONST.KYC_WALL_SOURCE.REPORT}
   227	            chatReportID={chatReportID}
   228	            iouReport={iouReport}
   229	            anchorAlignment={kycWallAnchorAlignment}
   230	            shouldShowPersonalBankAccountOption={shouldShowPersonalBankAccountOption}
   231	        >
   232	            {(triggerKYCFlow, buttonRef) => (
   233	                <ButtonWithDropdownMenu<PaymentType>
   234	                    success
   235	                    onOptionsMenuShow={onPaymentOptionsShow}
   236	                    onOptionsMenuHide={onPaymentOptionsHide}
   237	                    buttonRef={buttonRef}
   238	                    shouldAlwaysShowDropdownMenu={isInvoiceReport}
   239	                    customText={isInvoiceReport ? translate('iou.settlePayment', {formattedAmount}) : undefined}
   240	                    menuHeaderText={isInvoiceReport ? translate('workspace.invoices.paymentMethods.chooseInvoiceMethod') : undefined}
   241	                    isSplitButton={!isInvoiceReport}
   242	                    isDisabled={isDisabled}
   243	                    isLoading={isLoading}
   244	                    onPress={(event, iouPaymentType) => selectPaymentType(event, iouPaymentType, triggerKYCFlow)}
   245	                    pressOnEnter={pressOnEnter}
   246	                    options={paymentButtonOptions}
   247	                    onOptionSelected={(option) => {
   248	                        if (policyID === '-1') {
   249	                            return;
   250	                        }
   251	                        savePreferredPaymentMethod(policyID, option.value);
   252	                    }}
   253	                    style={style}
   254	                    wrapperStyle={wrapperStyle}
   255	                    disabledStyle={disabledStyle}
   256	                    buttonSize={buttonSize}
   257	                    anchorAlignment={paymentMethodDropdownAnchorAlignment}
   258	                    enterKeyEventListenerPriority={enterKeyEventListenerPriority}
   259	                    useKeyboardShortcuts={useKeyboardShortcuts}
   260	                />
   261	            )}
   262	        </KYCWall>
   263	    );
   264	}
